const ExplainerNavigation=(()=>{function selectHeading(entries,{readingLine,scrollY,maxScroll,preferredId=null,currentId=null}){const visible=entries.filter(e=>e.visible!==false).sort((a,b)=>a.top-b.top||a.order-b.order);if(!visible.length)return null;if(preferredId&&visible.some(e=>e.id===preferredId))return preferredId;if(maxScroll>1&&scrollY>=maxScroll-2)return visible.at(-1).id;const passed=visible.filter(e=>e.top<=readingLine+2);if(!passed.length)return visible[0].id;const lastTop=passed.at(-1).top;const tied=passed.filter(e=>Math.abs(e.top-lastTop)<=2);return(tied.find(e=>e.id===currentId)||tied[0]).id}return{selectHeading}})();if(typeof module!=="undefined"&&module.exports)module.exports=ExplainerNavigation;
